use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/queue-drain175";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let root=Path::new(R);let z=Path::new(Z);let m:Value=serde_json::from_slice(&fs::read(z.join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json")).unwrap()).unwrap();let audit:Value=serde_json::from_slice(&fs::read(root.join("source-audit.json")).unwrap()).unwrap();let mut exact=0;let mut pins=BTreeMap::new();
    for(p,h)in m["source_files_sha256"].as_object().unwrap(){let original=fs::read(z.join(p)).unwrap();assert_eq!(hash(z.join(p)),h.as_str().unwrap());let current=fs::read(root.join("source").join(p)).unwrap();let restored=if let Some(edit)=audit["edits"].get(p){let text=String::from_utf8(current.clone()).unwrap();let text=text.strip_suffix(edit["suffix"].as_str().unwrap()).unwrap();assert_eq!(text.lines().count(),String::from_utf8(original.clone()).unwrap().lines().count());if edit["after"].is_string(){let after=edit["after"].as_str().unwrap();assert_eq!(text.matches(after).count(),1);text.replacen(after,edit["before"].as_str().unwrap(),1).into_bytes()}else{text.as_bytes().to_vec()}}else{current.clone()};assert_eq!(restored,original,"source {p}");if current==original{exact+=1;}pins.insert(p.clone(),hash(root.join("source").join(p)));}
    assert_eq!(exact,172);assert_eq!(hash(root.join("queue_drain.rs")),hash(root.join("source/crates/zopro-core/src/msm_affine/queue_drain.rs")));
    let mut code=BTreeMap::new();for label in["control","candidate"]{let binary=root.join(format!("native/{label}-sdk"));let out=Command::new("nm").args(["-S","--defined-only"]).arg(&binary).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();let symbols=text.lines().filter(|line|line.contains("drain_queued_batches")).collect::<Vec<_>>();code.insert(label,json!({"binary":binary,"sha256":hash(&binary),"queue_drain_symbol_contexts":symbols}));}
    fs::write(root.join("final-source-review.json"),serde_json::to_vec_pretty(&json!({"all175_production_hashes_verified":true,"all175_reverse_exact":true,"original_line_positions_preserved":true,"originals_exact":exact,"field17_and_workspace_exact":true,"private_hashes":pins,"code":code})).unwrap()).unwrap();println!("Final source review:175 reverse exact/172 unchanged; original line positions, field and workspace preserved");
}
